conditions.source:
if (apiErr?.status === 409 && apiErr.body) {
        const conflictErr = new Error(apiErr.message) as ReservationConflictError;
        conflictErr.status = 409;
        conflictErr.conflict = apiErr.body.conflict || null;
        conflictErr.availableForYou = apiErr.body.available_for_you;
        throw conflictErr;
      }

if (
      uri.startsWith("http://") ||
      uri.startsWith("https://") ||
      uri.startsWith("blob:") ||
      uri.startsWith("data:") // expo-camera on web returns base64 data URIs
    ) {
      // Web / Expo Web: convert to a real Blob so multipart works
      const response = await fetch(uri);
      const blob = await response.blob();
      formData.append("file", blob, fileName);
    } else {
      // React Native (iOS / Android): use the RN FormData { uri, name, type } shorthand
      formData.append("file", { uri, name: fileName, type: mimeType } as unknown as Blob);
    }

if (visible) {
      setDiscount("0");
      setPaidNow("0");
      setDueDate("");
      setSelectedRentalIds(rentals.map((rental) => rental.id));
    }

if (maxDiscountAmount !== null && val.trim() !== "" && !Number.isNaN(numeric) && numeric > maxDiscountAmount) {
