    return { ...row, image_path: restoredPaths.get(row.image_path) };
  }

if (table === "app_settings" && row.key === "qr_code" && row.value && restoredPaths.has(row.value)) {
    return { ...row, value: restoredPaths.get(row.value) };
  }

if (missingTables.length) {
    throw new Error(`Restore cannot start because SQLite schema is missing: ${missingTables.join(", ")}`);
  }

if (!isShareAvailable) {
    throw new Error("This device cannot open the share sheet right now. Please try again later.");
  }

if (completedRows % 25 === 0 || completedRows === totalRows) {
      reportRestoreProgress(options, {
        stage: "tables",
        message: `Restored ${completedRows} of ${totalRows} database rows...`,
        completed: completedRows,
        total: totalRows,
        table,
      });
    }

if (useExec) {
      for (const table of DELETE_ORDER) {
        try {
          await db.execAsync(`DELETE FROM ${quoteSqlIdentifier(table)};`);
        } catch (error) {
          logRestoreDebug("Could not clear table before web restore", {
            table,
            error: error instanceof Error ? error.message : String(error),
          });
        }
      }
      return;
    }

if (tableFailures.length < 10) {
              tableFailures.push({
                table,
                id: row?.id,
                syncId: row?.sync_id,
                error: errorMessage,
              });
            }

if ((completedRows + skippedRows) % WEB_RESTORE_BATCH_SIZE === 0) {
            reportTableProgress(table);
            await waitForUiFrame();
          }

if (Platform.OS === "web") {
    logRestoreDebug("Using chunked web SQLite restore", {
      totalRows,
      batchSize: WEB_RESTORE_BATCH_SIZE,
    });
    const db = await getDatabase();
    await restoreIntoWebDatabase(db);
    reportRestoreProgress(options, {
      stage: "tables",
      message: "Finished writing web database rows...",
      completed: completedRows,
      total: totalRows,
    });
  } else {
    await withTransaction(restoreIntoDatabase);
  }

if (!isValidBackupPayload(parsed)) {
    logRestoreDebug("Backup validation failed", {
      format: (parsed as any)?.format,
      version: (parsed as any)?.version,
      hasTables: Boolean((parsed as any)?.tables),
    });
    throw new Error("This file is not a valid NB Tools backup.");
  }

if ((parsed.app?.schemaVersion || 0) > SCHEMA_VERSION) {
    throw new Error("This backup was created by a newer version of the app and cannot be restored here yet.");
  }

if (!fileCount) {
      reportRestoreProgress(options, {
        stage: "files",
        message: "No embedded files to restore.",
        completed: 0,
        total: 0,
      });
    }

if (criticalMismatchedTables.length) {
      const failureSummary = tableFailures.length
        ? ` First errors: ${tableFailures.map((failure) => `${failure.table}${failure.id ? `#${failure.id}` : ""}: ${failure.error}`).join(" | ")}`
        : "";
      throw new Error(
        `Restore verification failed for: ${criticalMismatchedTables.join(", ")}${
          skippedRows ? ` (${skippedRows} row${skippedRows === 1 ? "" : "s"} were skipped)` : ""
        }.${failureSummary}`
      );
    }

if (Platform.OS === "web") {
      reportRestoreProgress(options, {
        stage: "cleanup",
        message: "Saving restored web database...",
      });
      try {
        await persistDatabase();
      } catch (error) {
        persistenceWarning =
          "The restore is visible in this browser session, but the web database snapshot could not be saved. Refreshing the page may lose the restored data.";
        logRestoreDebug("Web database persistence failed after restore", {
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }

if (!isValidBackupPayload(parsed)) {
    throw new Error("This file is not a valid NB Tools backup.");
  }

if (
    IS_WEB &&
    databaseState.db &&
    databaseState.db.databasePath !== WEB_DB_NAME &&
    databaseState.db.databasePath !== WEB_FALLBACK_DB_NAME
  ) {
    try {
      await databaseState.db.closeAsync();
    } catch {
      // Ignore stale in-memory web database close failures during hot reload.
    }
    resetDatabaseState();
  }

if (!databaseState.dbPromise) {
    const openPromise = IS_WEB ? openWebDatabase() : SQLite.openDatabaseAsync("nbtools-offline.db");
    databaseState.dbPromise = openPromise.then((db) => {
      databaseState.db = db;
      return db;
    });
  }

if (!databaseState.foreignKeysEnabled) {
    await db.execAsync("PRAGMA foreign_keys = ON;");
    databaseState.foreignKeysEnabled = true;
  }

if (!databaseState.initPromise) {
    databaseState.initPromise = (async () => {
      const db = await getDatabase();
      await runMigrations(db);
      await persistIfNeeded();
      return db;
    })();
  }

if (!columns.has(columnName)) {
    await db.execAsync(`ALTER TABLE ${tableName} ADD COLUMN ${columnName} ${sqlDefinition}`);
  }

if (!row.sync_id) {
      await db.runAsync(`UPDATE ${tableName} SET sync_id = ? WHERE id = ?`, makeSyncId(), row.id);
    }

if (updatedAtSql) {
    await db.execAsync(
      `UPDATE ${tableName}
       SET updated_at = COALESCE(updated_at, ${updatedAtSql})
       WHERE updated_at IS NULL OR updated_at = ''`
    );
  }

if (quantity > 0) {
        await insertInventoryTransaction(newEquipmentId, "Create", quantity, unitPrice, 0, quantity, "Initial stock");
        await insertExpense(
          "Equipment Purchase",
          quantity * unitPrice,
          `Initial purchase for ${payload.name?.trim() || "equipment"} (${quantity} unit${quantity === 1 ? "" : "s"} x ${unitPrice})`
        );
      }

if (payload.images) {
      await run(`DELETE FROM equipment_images WHERE equipment_id = ?`, id);
      for (const [index, image] of payload.images.entries()) {
        await run(`INSERT INTO equipment_images (equipment_id, image_path, sort_order) VALUES (?, ?, ?)`, id, image, index);
      }
    }

if (action === "Repair" && (cost || 0) > 0) {
        await insertExpense("Repair Cost", cost || 0, `${existing.name}${remark?.trim() ? ` - ${remark.trim()}` : " repair"}`);
      }

if (existing) {
      await localUsersRepo.updatePassword(username, passwordHash, passwordSalt);
      return;
    }

if (quantityDelta > 0) {
        const equipment = await getFirst<{ stock_count: number }>(`SELECT stock_count FROM equipment WHERE id = ?`, rental.equipment_id);
        if (!equipment) throw new Error("Equipment not found");
        if (equipment.stock_count < quantityDelta) throw new Error("Not enough stock available");
      }

if (rental.status === "Active") {
        const quantity = Math.max(rental.quantity || 1, 1);
        await run(`UPDATE equipment SET stock_count = stock_count + ?, updated_at = ?, sync_status = 'pending' WHERE id = ?`, quantity, cancelledAt, rental.equipment_id);
        await markPendingById("equipment", rental.equipment_id, cancelledAt);
      }

if (!result.changes) {
      await run(
        `INSERT INTO app_settings (key, value)
         VALUES (?, ?)`,
        key,
        value
      );
    }

