if (invoiceQuery.isLoading) {
    return (
      <SafeAreaView style={styles.center} edges={["top", "bottom", "left", "right"]}>
        <ActivityIndicator size="large" color={c.primary} />
      </SafeAreaView>
    );
  }

if (invoiceQuery.isError || !invoiceQuery.data) {
    return (
      <SafeAreaView style={styles.center} edges={["top", "bottom", "left", "right"]}>
        <MaterialCommunityIcons name="file-alert-outline" size={40} color={c.textMuted} />
        <Text style={styles.errorText}>
          {(invoiceQuery.error as any)?.message ||
            "Invoice isn't available yet — it appears once this rental is completed."}
        </Text>
      </SafeAreaView>
    );
  }

if (!forgotUsername.trim()) {
      setForgotError("Enter your username first.");
      return;
    }

if (result.reset_code_for_demo) {
        setResetCode(result.reset_code_for_demo);
        setDemoCodeHint(
          "Email/SMS delivery isn't configured for this shop yet, so your reset code is shown here — enter it below.",
        );
      }

if (!resetCode.trim() || !newPassword) {
      setForgotError("Enter the reset code and a new password.");
      return;
    }

