    throw new Error("Unable to read selected image");
  }

if (!baseDir) {
    throw new Error("File storage is not available on this device.");
  }

if (typeof document === "undefined") {
    throw new Error("Browser download is not available here.");
  }

if (Platform.OS === "web") {
    return {
      uri: downloadTextInBrowser(contents, fileName),
      method: "download" as const,
    };
  }

if (Platform.OS === "android") {
    const safeName = sanitizeFileName(fileName);
    const extensionIndex = safeName.lastIndexOf(".");
    const baseName = extensionIndex > 0 ? safeName.slice(0, extensionIndex) : safeName;

    const permissions = await FileSystem.StorageAccessFramework.requestDirectoryPermissionsAsync(
      FileSystem.StorageAccessFramework.getUriForDirectoryInRoot("Download")
    );

    if (!permissions.granted || !permissions.directoryUri) {
      throw new Error("Backup export was cancelled before a save folder was selected.");
    }

    const targetUri = await FileSystem.StorageAccessFramework.createFileAsync(
      permissions.directoryUri,
      baseName,
      "application/json"
    );

    await FileSystem.writeAsStringAsync(targetUri, contents, { encoding: FileSystem.EncodingType.UTF8 });

    return {
      uri: targetUri,
      method: "directory" as const,
      localUri,
    };
  }

if (!permissions.granted || !permissions.directoryUri) {
      throw new Error("Backup export was cancelled before a save folder was selected.");
    }

if (path.startsWith(webFilePrefix)) {
    if (!canUseWebStorage()) return null;
    const stored = window.localStorage.getItem(path.slice(webFilePrefix.length));
    const parsed = stored ? parseDataUrl(stored) : null;
    if (!parsed) return null;
    return {
      fileName: path.slice(webFilePrefix.length),
      mimeType: parsed.mimeType,
      base64: parsed.base64,
    };
  }

if (dataUrlMatch) {
    return {
      fileName: path.split("/").pop() || "file.bin",
      mimeType: dataUrlMatch.mimeType,
      base64: dataUrlMatch.base64,
    };
  }

if (Platform.OS === "web" || !baseDir) {
    const dataUrl = `data:${mimeType || "application/octet-stream"};base64,${base64}`;
    if (!canUseWebStorage()) {
      return dataUrl;
    }

    const storageKey = getWebStorageKey(fileName);
    try {
      window.localStorage.setItem(storageKey, dataUrl);
      return `${webFilePrefix}${storageKey}`;
    } catch {
      console.warn("Browser localStorage is full; restoring image as a data URL in SQLite instead.", { fileName });
      return dataUrl;
    }
  }

if (
    path.startsWith("http://") ||
    path.startsWith("https://") ||
    path.startsWith("data:") ||
    path.startsWith("blob:") ||
    path.startsWith("content://")
  ) {
    return;
  }

if (
    path.startsWith("http://") ||
    path.startsWith("https://") ||
    path.startsWith("data:") ||
    path.startsWith("content://")
  ) {
    return path;
  }

if (!updated.changes) {
    await run(`INSERT INTO app_settings (key, value) VALUES (?, ?)`, key, value);
  }

if (!meta.last_synced_at) {
    await run(`DELETE FROM sync_tombstones WHERE entity_type = ? AND sync_id = ?`, entityType, meta.sync_id);
    return;
  }

if (existingId) {
    await run(
      `UPDATE categories
       SET name = ?, created_at = ?, updated_at = ?, sync_status = 'synced', last_synced_at = ?, server_updated_at = ?
       WHERE id = ?`,
      record.name,
      record.created_at,
      record.updated_at,
      syncedAt,
      record.updated_at,
      existingId
    );
    return;
  }

